// Original VisionicX lessons. Methods share the same worked question; cases are parameterized practice, not past papers.
const list=[];
function add(id,title,area,topic,level,formula,idea,origin,condition,real,trap,build){list.push({id,title,area,topic,level,formula,idea,origin,condition,real,trap,build});}
const methods=(...items)=>items.map(([title,body])=>({title,steps:body.split('|')}));
const pack=(prompt,answer,ways,unit='',visual=null,options=null)=>({prompt,answer,ways,unit,visual,options});
const f=x=>Number(x.toFixed(6));
add('simplify','Simplification & order of operations','Arithmetic','Number foundations','Foundation','Brackets → powers → × and ÷ → + and −','An expression is a set of instructions. Multiplication and division have equal priority; evaluate them left to right.','Grouping symbols tell us which quantity is treated as one input. The priority convention removes ambiguity when grouping is omitted.','Do not treat the letters in BODMAS as a strict order between × and ÷, or + and −.','Calculate the total price of identical packs plus a delivery charge.','Adding before multiplying changes the question.',n=>{let a=3+n,b=8+2*n,c=6+n,r=a*b+c;return pack(`Evaluate ${a} × (${b-2} + 2) + ${c}.`,r,methods(['Bracket first',`${b-2}+2=${b}.|Multiply ${a}×${b}=${a*b}.|Add ${c}: ${r}.`],['Distributive expansion',`${a}×${b-2}+${a}×2+${c}.|${a*(b-2)}+${a*2}+${c}=${r}.`],['Equal groups',`There are ${a} groups of ${b}, giving ${a*b}.|Add the separate ${c} items: ${r}.`],['Compensate',`${b} is ${b+2}−2.|${a}×${b+2}−${a*2}+${c}=${r}.`],['Inverse check',`Subtract ${c} from ${r}: ${a*b}.|Divide by ${a}: ${b}, the bracket value.`]));});
add('fractions','Fractions of a quantity','Arithmetic','Number foundations','Foundation','part = whole × numerator / denominator','A fraction divides a whole into equal shares and chooses some of them.','If a whole W is split into d equal shares, each share is W/d. Taking k shares gives kW/d.','The denominator must be nonzero. These examples use positive wholes.','Share a batch of ingredients or reserve part of a budget.','A fraction of a quantity is multiplication, not addition.',n=>{let d=4+n,k=d-1,w=d*24,r=k*24;return pack(`Find ${k}/${d} of ${w}.`,r,methods(['Divide, then multiply',`${w}÷${d}=24 per share.|Take ${k} shares: 24×${k}=${r}.`],['Multiply, then divide',`${w}×${k}=${w*k}.|Divide by ${d}: ${r}.`],['Complement',`${k}/${d}=1−1/${d}.|${w}−24=${r}.`],['Cancel first',`(${w}/${d})×${k}=24×${k}.|Cancellation is between factors, giving ${r}.`],['Ratio model',`Selected : total = ${k}:${d}.|One ratio unit is 24; selected quantity is ${r}.`]),'',{type:'bar',values:[r,w-r],labels:['Selected','Remaining']});});
add('hcf','HCF / greatest common divisor','Arithmetic','Number foundations','Foundation','gcd(a,b) = gcd(b, a mod b)','The greatest common divisor is the largest positive integer dividing both numbers.','A common divisor of a and b also divides a−kb. Repeating this reduction gives Euclid’s algorithm.','Use positive integers; factor multiplicity matters.','Cut two ribbons into equal lengths with no waste.','The greatest common divisor is not the smallest common multiple.',n=>{let g=4+n,a=3*g,b=5*g;return pack(`Find the HCF of ${a} and ${b}.`,g,methods(['List divisors',`The numbers are 3×${g} and 5×${g}.|Since 3 and 5 share no factor above 1, the largest shared factor is ${g}.`],['Euclidean division',`${b} mod ${a}=${2*g}.|${a} mod ${2*g}=${g}; ${2*g} mod ${g}=0.|The last nonzero remainder is ${g}.`],['Repeated subtraction',`${b}−${a}=${2*g}.|${a}−${2*g}=${g}.|${2*g}−${g}=${g}, so the HCF is ${g}.`],['Common scaling',`gcd(3,5)=1.|Scaling both by ${g} scales their HCF to ${g}.`],['Factor pairs',`${a}=${g}×3 and ${b}=${g}×5.|Any additional shared multiplier must divide both 3 and 5; none does.`]));});
add('lcm','LCM & repeating events','Arithmetic','Number foundations','Foundation','lcm(a,b) = ab / gcd(a,b)','The least common multiple is the earliest positive point where two integer cycles meet.','In prime factorizations, the HCF uses minimum exponents and the LCM uses maximum exponents; multiplying them reconstructs ab.','The product rule here is for two positive integers.','Two lights flash at different intervals; find when they next flash together.','Multiplying the numbers overcounts when they have a common factor.',n=>{let g=n+2,a=3*g,b=4*g,r=12*g;return pack(`Two signals repeat every ${a} and ${b} seconds. They flash together now. When do they next coincide?`,r,methods(['List multiples',`${a}, ${2*a}, ${3*a}, ${4*a}.|${b}, ${2*b}, ${3*b}.|The first shared positive time is ${r}.`],['HCF product rule',`HCF(${a},${b})=${g}.|${a}×${b}÷${g}=${r}.`],['Reduce the cycles',`The intervals are ${g}×3 and ${g}×4.|LCM(3,4)=12, so the time is ${g}×12=${r}.`],['Find the multiplier',`A multiple of ${a} must also divide by ${b}.|The smallest multiplier is 4: 4×${a}=${r}.`],['Timeline check',`${r}÷${a}=4 cycles and ${r}÷${b}=3 cycles.|The reduced multipliers 3 and 4 are coprime, so no smaller positive coincidence exists.`]),'seconds');});
add('remainder','Remainders & divisibility','Arithmetic','Number foundations','Foundation','a = dq + r, 0 ≤ r < d','Division separates complete groups from the leftover amount.','Choose the largest whole number q for which dq≤a; the remaining amount a−dq is smaller than d.','The divisor d is positive and the remainder is a nonnegative integer smaller than it.','Pack items into boxes and count leftovers.','A remainder equal to the divisor contains another full group.',n=>{let d=7+n,q=12+n,r=3,a=d*q+r;return pack(`What is the remainder when ${a} is divided by ${d}?`,r,methods(['Nearest lower multiple',`${d}×${q}=${a-r}.|${a}−${a-r}=3.`],['Division identity',`${a}=${d}×${q}+3.|The remainder is 3 since 0≤3<${d}.`],['Remove groups',`Remove ${q} complete groups of ${d}.|Three items remain.`],['Reduce a known multiple',`${a} mod ${d}=(${a-r}+3) mod ${d}.|The first term has remainder 0; the result is 3.`],['Check the upper bound',`The next multiple is ${a-r+d}, above ${a}.|Therefore the preceding multiple leaves exactly 3.`]));});
add('ratio','Ratio & sharing','Arithmetic','Ratios & percentages','Foundation','share A = total × a / (a+b)','A ratio compares quantities through a common unit.','Write the two shares as ak and bk. Their total is (a+b)k, so k=total/(a+b).','The total ratio units must be positive; all shares use the same units.','Split a team budget or a prize in an agreed ratio.','Using a/b of the total confuses part-to-part with part-to-whole.',n=>{let a=2+n,b=3,t=(a+b)*40,r=a*40;return pack(`Share ₹${t} in the ratio ${a}:${b}. How much does the first person receive?`,r,methods(['Unitary method',`${a}+${b}=${a+b} ratio units.|One unit is ${t}÷${a+b}=40.|First share=${a}×40=${r}.`],['Fraction of the whole',`First share is ${a}/${a+b} of the total.|${t}×${a}/${a+b}=${r}.`],['Equation',`Let the first and second shares be ${a}k and ${b}k.|${a+b}k=${t}, so k=40.|First share=${r}.`],['Find the other share',`Second share=${b}×40=${b*40}.|Subtract it from ${t}: ${r}.`],['Scaling a model',`A model split of ${a} and ${b} totals ${a+b}.|Scale every model unit by 40: first share ${r}.`]),'rupees',{type:'bar',values:[r,b*40],labels:['First share','Second share']});});
add('proportion','Direct proportion','Arithmetic','Ratios & percentages','Foundation','y₂ = y₁ × x₂/x₁','In a direct proportion, the output per input unit stays constant.','If y=kx, dividing by x gives the unit rate k. Use the same rate at a new input.','Assumes a constant rate with no fixed charge.','Price identical notebooks or scale a recipe.','A setup fee breaks direct proportionality.',n=>{let a=3+n,b=a+2,rate=20+n*5,r=b*rate;return pack(`${a} identical notebooks cost ₹${a*rate}. What do ${b} cost at the same unit price?`,r,methods(['One-unit price',`${a*rate}÷${a}=${rate}.|${b}×${rate}=${r}.`],['Scale factor',`Multiply the original price by ${b}/${a}.|${a*rate}×${b}/${a}=${r}.`],['Cross multiplication',`Price/${b}=${a*rate}/${a}.|Price=${r}.`],['Add the extra units',`There are 2 extra notebooks.|Add 2×${rate} to ${a*rate}: ${r}.`],['Linear model',`Cost C(x)=${rate}x.|C(${b})=${r}; there is no fixed charge.`]),'rupees');});
add('percentage','Percentages & mental conversion','Arithmetic','Ratios & percentages','Foundation','p% of W = pW/100','Percent means out of one hundred, so it expresses a fraction of a base quantity.','Split W into 100 equal shares. Selecting p shares gives p×W/100.','Always identify the base. Percent is a rate, not an absolute amount.','Calculate a discount, tax or survey share.','15% means 0.15, not 15, when used as a multiplier.',n=>{let p=15,w=200+40*n,r=w*p/100;return pack(`Find ${p}% of ${w}.`,r,methods(['Decimal multiplier',`15%=0.15.|0.15×${w}=${r}.`],['10% plus 5%',`10%=${w/10}; 5%=${w/20}.|Add them: ${r}.`],['Fraction conversion',`15/100=3/20.|${w}÷20×3=${r}.`],['One-percent unit',`1%=${w/100}.|15 shares total ${r}.`],['Swap the factors',`15% of ${w} = ${w}% of 15.|Both equal 15×${w}/100=${r}; choose the easier product.`]),'',{type:'bar',values:[r,w-r],labels:['15% part','85% remainder']});});
add('percent-change','Percentage increase & decrease','Arithmetic','Ratios & percentages','Foundation','change% = (new−old)/old × 100','Percentage change compares the difference with the original value.','The change is new−old. Dividing by old measures change per original unit; ×100 expresses it per hundred.','Original value must be nonzero. Positive bases are used here.','Measure sales growth or a change in a bill.','Dividing by the new value answers a different question.',n=>{let a=200+40*n,b=1.25*a;return pack(`A value rises from ${a} to ${b}. What is the percentage increase?`,25,methods(['Difference / original',`${b}−${a}=${b-a}.|${b-a}/${a}×100=25%.`],['Growth factor',`${b}/${a}=1.25.|(1.25−1)×100=25%.`],['Recognize the fraction',`The increase ${b-a} is one quarter of ${a}.|1/4=25%.`],['One-percent unit',`1% of the old value is ${a/100}.|${b-a}÷${a/100}=25 percent units.`],['Reverse verify',`25% of ${a}=${a/4}.|${a}+${a/4}=${b}, confirming the increase.`]),'percent');});
add('successive','Successive percentage changes','Arithmetic','Ratios & percentages','Intermediate','net% = a+b+ab/100','Successive changes multiply because the second change uses the already changed value.','(1+a/100)(1+b/100)=1+(a+b)/100+ab/10000. Subtract 1 and multiply by 100.','Use signed rates: decreases are negative. For physical quantities, each growth factor should be nonnegative.','Compare a salary rise followed by a pay reduction.','An equal percentage rise and fall do not cancel.',n=>{let p=10+5*n,q=-10,r=p+q+p*q/100;return pack(`A value rises ${p}% then falls 10%. What is the net percentage change?`,r,methods(['Multiply factors',`(1+${p}/100)×0.9=${1+r/100}.|Subtract 1 and multiply by 100: ${r}%.`],['Start from 100',`100 becomes ${100+p}.|After a 10% fall it is ${100+r}.|Net change=${r}%.`],['Expanded formula',`${p}+(−10)+${p}×(−10)/100.|Result=${r}%.`],['Separate the loss',`The rise adds ${p} per 100.|The later loss is 10+${p/10}; net is ${p}−${10+p/10}=${r}.`],['Track retained rise',`90% of the original 100 remains: 90.|90% of the added ${p} remains: ${p*.9}.|Total ${100+r}, so change ${r}%.`]),'percent');});
add('profit','Profit & loss','Arithmetic','Commercial arithmetic','Foundation','profit% = (SP−CP)/CP ×100','Profit is the excess of selling price over cost price. The cost is the comparison base.','Profit=SP−CP; each rupee of cost contributes profit/CP rupees of profit. Multiply by 100 for percent.','Cost price must be positive; include the costs specified in the problem.','Check margins on a small business purchase.','Profit as a percent of selling price is a margin, not this markup rate.',n=>{let c=400+80*n,s=c*1.2;return pack(`An item costs ₹${c} and sells for ₹${s}. Find the profit percentage.`,20,methods(['Difference method',`Profit=${s}−${c}=${s-c}.|${s-c}/${c}×100=20%.`],['Selling factor',`${s}/${c}=1.2.|The excess factor 0.2 gives 20%.`],['Fraction shortcut',`Profit ${s-c} is one fifth of cost ${c}.|1/5=20%.`],['One-percent cost',`1% of cost=${c/100}.|${s-c}÷${c/100}=20.`],['Reverse check',`20% of ₹${c} is ₹${c*.2}.|Cost plus profit equals ₹${s}.`]),'percent');});
add('discount','Discount & marked price','Arithmetic','Commercial arithmetic','Foundation','SP = MP(1−d/100)','A discount removes a percentage of the marked price.','The marked price is 100% of itself; after removing d%, the customer pays (100−d)%.','Discount base is the marked price. Taxes and additional charges are excluded unless stated.','Compare a shop sale with a coupon offer.','Discount percentage and profit percentage usually use different bases.',n=>{let m=800+200*n,r=.75*m;return pack(`The marked price is ₹${m}. Find the selling price after a 25% discount.`,r,methods(['Subtract discount',`25% of ${m}=${m/4}.|${m}−${m/4}=${r}.`],['Retained percentage',`100−25=75%.|0.75×${m}=${r}.`],['Fraction shortcut',`75%=3/4.|${m}÷4×3=${r}.`],['Price per hundred',`Each ₹100 becomes ₹75.|There are ${m/100} hundreds; multiply by 75: ${r}.`],['Reverse check',`${r}/0.75=${m}.|The discount is ${m-r}, exactly one quarter of ${m}.`]),'rupees');});
add('simple-interest','Simple interest','Arithmetic','Commercial arithmetic','Foundation','I = Prt/100','Simple interest uses the original principal as the base in every time period.','One year earns Pr/100. A constant t-year duration earns t copies of that amount.','r is a yearly percentage and t is in years. This model does not compound.','Estimate earnings under a stated simple-interest agreement.','Months must be converted to years for an annual rate.',n=>{let p=1000+500*n,r=8,t=3,a=p*r*t/100;return pack(`Find simple interest on ₹${p} at 8% per year for 3 years.`,a,methods(['Formula substitution',`${p}×8×3/100=${a}.|Interest excludes the principal.`],['One year first',`Yearly interest=${p*.08}.|Three years earn ${a}.`],['Total simple rate',`8%×3=24% of the original principal.|${p}×0.24=${a}.`],['Split 24%',`20%=${p*.2}; 4%=${p*.04}.|Add: ${a}.`],['Monthly model',`At simple interest, monthly interest=${f(p*.08/12)}.|36 months earn ${a}; keep the fraction unrounded until the end.`]),'rupees');});
add('compound','Compound growth','Arithmetic','Commercial arithmetic','Intermediate','A = P(1+r/100)ⁿ','Compounding applies each period’s rate to the updated amount.','A₁=P(1+r/100). Repeating the same multiplication n times gives P(1+r/100)ⁿ.','Rate and period must match. These examples use annual compounding and no withdrawals.','Model repeated annual growth of a deposit or population.','Subtract the principal if the question asks for interest rather than final amount.',n=>{let p=1000+500*n,a=p*1.21;return pack(`₹${p} grows 10% each year, compounded annually for 2 years. Find the final amount.`,a,methods(['Power formula',`${p}×1.1².|1.1²=1.21, giving ${a}.`],['Year by year',`Year 1: ${p}×1.1=${p*1.1}.|Year 2: ${p*1.1}×1.1=${a}.`],['Binomial expansion',`(1+0.1)²=1+0.2+0.01.|${p}×1.21=${a}.`],['Interest split',`First interest=${p*.1}.|Second interest=${p*.11}.|Add both to ${p}: ${a}.`],['Net growth rate',`10+10+10×10/100=21%.|121% of ${p}=${a}.`]),'rupees');});
add('average','Averages & total recovery','Arithmetic','Averages & mixtures','Foundation','mean = sum / count','An average is the equal share of the total across all entries.','If n values are replaced by the same value m without changing the total, nm=sum, so m=sum/n.','The ordinary mean weights every entry equally.','Find a daily average or recover a missing total.','The average of averages is valid only with equal group sizes.',n=>{let a=12+n*4,v=[a-4,a-2,a,a+2,a+4];return pack(`Find the mean of ${v.join(', ')}.`,a,methods(['Sum and divide',`Total=${5*a}.|Divide by 5: ${a}.`],['Assumed mean',`Take ${a} as a reference.|Deviations −4,−2,0,2,4 sum to 0, so mean=${a}.`],['Pair endpoints',`${v[0]}+${v[4]}=${2*a}; ${v[1]}+${v[3]}=${2*a}.|Add middle ${a}; total ${5*a}, mean ${a}.`],['AP midpoint',`Differences are all 2.|For this arithmetic progression, mean=(first+last)/2=${a}.`],['Equal-share balancing',`Move 4 from the largest to smallest and 2 from the next largest to next smallest.|All five become ${a}; the total is preserved.`]),'',{type:'columns',values:v,labels:v.map((_,i)=>'Day '+(i+1))});});
add('weighted','Weighted averages','Arithmetic','Averages & mixtures','Intermediate','mean = Σ(wx)/Σw','A group’s influence depends on how many entries it represents.','Group i contributes wᵢxᵢ to the total. Divide the sum of those contributions by the total count.','Weights are nonnegative and their sum is positive.','Combine test averages from classes of different sizes.','A small group should not count as much as a large one unless the task specifies equal weights.',n=>{let a=40+5*n,b=a+20,r=a+15;return pack(`10 scores average ${a}; 30 other scores average ${b}. Find the combined mean.`,r,methods(['Total method',`Total=10×${a}+30×${b}=${40*r}.|Count=40, mean=${r}.`],['Weight fractions',`The groups occupy 1/4 and 3/4 of all scores.|${a}/4+3×${b}/4=${r}.`],['Assumed lower mean',`Start with ${a} for everyone.|30 scores add 20 each: 600 extra over 40.|Add 15: ${r}.`],['Balance deviations',`At ${r}, 10 lower scores have deficit 15 each.|30 upper scores have surplus 5 each; both totals are 150.`],['Reduce the ratio',`Group sizes are 1:3.|(${a}+3×${b})/4=${r}.`]),'',{type:'bar',values:[10,30],labels:['Lower group','Higher group']});});
add('mixture','Mixtures & alligation','Arithmetic','Averages & mixtures','Intermediate','low quantity / high quantity = (high−mean)/(mean−low)','A mixture’s concentration is a weighted average of its ingredients.','Balance the shortfall of the low-concentration ingredient with the excess of the high-concentration ingredient: qL(m−L)=qH(H−m).','Two ingredients; same concentration units; target strictly between the two levels.','Blend solutions or two grades of a commodity.','Alligation gives a ratio of quantities, not their individual concentrations.',n=>{let l=10+n*5,h=l+30,m=l+20;return pack(`Mix ${l}% and ${h}% solutions to get ${m}%. What is the low : high quantity ratio?`,'1:2',methods(['Alligation',`High−target=${h-m}; target−low=${m-l}.|Low:high=10:20=1:2.`],['Balance equation',`qL×20=qH×10.|qL/qH=1/2, so 1:2.`],['One plus two units',`Try 1 unit at ${l}% and 2 units at ${h}%.|(${l}+2×${h})/3=${m}%.`],['High fraction',`High fraction=(target−low)/(high−low)=20/30=2/3.|Low fraction=1/3, so 1:2.`],['Deviation picture',`Each low unit has a 20-point deficit.|Each high unit has a 10-point excess.|Two high units balance one low unit.`]),'',null,['1:2','2:1','1:3','3:1']);});
add('partnership','Partnership & time-weighted capital','Arithmetic','Commercial arithmetic','Intermediate','profit share ∝ capital × invested time','If agreed profit sharing is proportional to capital-time, each amount is weighted by how long it was invested.','A unit of capital invested for one period defines one capital-time unit. Summing these units gives the agreed ratio.','Use only when the agreement specifies this sharing rule; use matching time units.','Split an illustrative partnership profit.','Equal investments need not earn equal shares if durations differ.',n=>{let c=1000+200*n,p=600+120*n,r=p/3;return pack(`A invests ₹${c} for 6 months; B invests ₹${c} for 12 months. Profit ₹${p} is shared by capital-time. Find A’s share.`,r,methods(['Capital-time products',`A:B=${c}×6 : ${c}×12 =1:2.|A receives 1/3 of ${p}=${r}.`],['Cancel equal capitals',`Capitals are equal, so only duration varies.|6:12=1:2; A’s share=${r}.`],['Ratio units',`There are 3 total ratio units.|One is ${p}/3=${r}; A has one unit.`],['Equation',`B receives twice A. Let A’s share be x.|x+2x=${p}, so x=${r}.`],['Other share',`B gets 2/3 of ${p}=${2*r}.|Remaining profit=${r}.`]),'rupees');});
add('ages','Age equations','Quantitative','Equations & sequences','Foundation','future age = present age + elapsed years','The same elapsed time is added to everyone’s age, so age differences stay constant.','Time moves both ages by the same amount. A future ratio becomes an equation in the present ages.','Ratios can change; differences stay fixed. Ages here are nonnegative.','Translate a timeline into an equation.','Ages do not keep the same ratio as time passes.',n=>{let y=10+n,p=2*y,t=5,r=p+t;return pack(`A is twice B’s present age. B is ${y} years old. How old will A be in 5 years?`,r,methods(['Present, then future',`A now=2×${y}=${p}.|After 5 years: ${r}.`],['Timeline',`Place A at ${p} on the age line.|Move 5 units right to ${r}.`],['Equation',`A−5=2×${y}, where A is the requested future age.|A=${r}.`],['Difference invariant',`Present age gap=${y}.|B in 5 years=${y+5}; add the same gap: ${r}.`],['Avoid ratio trap',`Twice B’s future age would be ${2*(y+5)}, too high by 5.|Subtract that extra 5: ${r}.`]),'years');});
add('work','Time & work','Quantitative','Rates & movement','Intermediate','combined rate = 1/a + 1/b; time = 1/rate','Work rates add when people work simultaneously at unchanged independent rates.','A worker finishing one job in a days completes 1/a job per day. Add daily fractions, then divide the job by the combined rate.','Same job, constant rates, no interference and no idle time.','Estimate completion when two teams combine.','Adding finishing times does not produce a combined finishing time.',n=>{let k=n+2,a=3*k,b=6*k,r=2*k;return pack(`A finishes a job in ${a} days and B in ${b} days. At constant rates, how long together?`,r,methods(['Fractional rates',`1/${a}+1/${b}=3/${b}=1/${r}.|One job takes ${r} days.`],['LCM work units',`Let the job contain ${b} units.|A does 2/day and B 1/day.|${b}÷3=${r} days.`],['Product over sum',`Time=ab/(a+b).|${a}×${b}/(${a}+${b})=${r}.`],['Relative efficiency',`A is twice as fast as B.|Together they are three times B’s rate.|${b}÷3=${r}.`],['Fraction completion check',`In ${r} days A finishes 2/3 and B 1/3.|Their fractions total 1 job.`]),'days');});
add('pipes','Pipes, filling & leaks','Quantitative','Rates & movement','Intermediate','net rate = filling rate − draining rate','An inlet increases the tank contents; a leak decreases them. Use signed rates.','Track one unit tank per hour. The net change is the sum of positive inlet and negative outlet contributions.','Tank initially empty; constant rates; inlet and outlet operate together. A nonpositive net rate cannot fill it.','Model filling a tank with a constant leak.','Use a minus sign for an outlet; not every pipe fills.',n=>{let k=n+2,a=2*k,b=6*k,r=3*k;return pack(`An inlet fills a tank in ${a} hours; a leak empties a full tank in ${b} hours. How long to fill an empty tank with both open?`,r,methods(['Signed fractions',`1/${a}−1/${b}=2/${b}=1/${r}.|Filling takes ${r} hours.`],['Capacity units',`Set tank capacity to ${b} units.|Inlet adds 3/hour; leak removes 1/hour.|${b}/2=${r}.`],['Product over difference',`ab/(b−a)=${a}×${b}/(${b}−${a}).|Result=${r}.`],['Leak fraction',`Leak rate is one third of inlet rate.|Retain two thirds of inlet efficiency; time=${a}×3/2=${r}.`],['Net volume check',`In ${r} hours inlet adds 1.5 tanks and leak removes 0.5.|Net is one full tank.`]),'hours');});
add('speed','Speed, distance & time','Quantitative','Rates & movement','Foundation','distance = speed × time','Constant speed measures distance covered per time unit.','If each hour adds v distance units, t hours add vt units. Rearranging gives t=d/v.','Use compatible distance/time units and positive speed.','Plan journey time under a constant-speed model.','km/h cannot be multiplied directly by minutes without conversion.',n=>{let v=40+10*n,t=3,d=v*t;return pack(`How far does a vehicle travel at ${v} km/h for 3 hours at constant speed?`,d,methods(['Multiply units',`${v} km/hour ×3 hours.|Hours cancel, leaving ${d} km.`],['Repeated addition',`${v}+${v}+${v}=${d}.|This works because each hour covers the same distance.`],['Unitary method',`1 hour gives ${v} km.|3 hours gives ${d} km.`],['Minute conversion',`180 minutes at ${v}/60 km per minute.|(${v}/60)×180=${d}; keep fractions exact.`],['Reverse time check',`${d} km ÷${v} km/h=3 hours.|The recovered time matches the given value.`]),'km');});
add('average-speed','Average speed on equal distances','Quantitative','Rates & movement','Intermediate','v̄ = 2uv/(u+v)','Average speed is total distance divided by total elapsed time.','For two equal distances d, total time is d/u+d/v. Dividing 2d by that sum cancels d and yields the harmonic mean.','Distances must be equal. For equal times, use the ordinary mean instead.','Compare outbound and return journey speeds.','The simple average of speeds is wrong for unequal travel times.',n=>{let u=20+10*n,v=2*u,r=4*u/3;return pack(`Travel equal distances at ${u} and ${v} km/h. Find the average speed (round to 6 decimals).`,f(r),methods(['Choose a distance',`Use ${2*u} km for each leg.|Times are 2 h and 1 h; total distance ${4*u}, total time 3.|Average=${f(r)} km/h.`],['Harmonic mean',`2×${u}×${v}/(${u}+${v}).|Result=${f(r)}.`],['Rate reciprocals',`Mean time per km=(1/${u}+1/${v})/2.|Invert it: ${f(r)} km/h.`],['Time weights',`The slower leg takes twice the time.|Weighted speed=(2×${u}+${v})/3=${f(r)}.`],['Ratio scaling',`For speeds 1 and 2, equal-distance mean is 4/3.|Scale by ${u}: ${f(r)}.`]),'km/h');});
add('relative-speed','Relative speed & meetings','Quantitative','Rates & movement','Intermediate','closing speed = u+v (toward each other)','Relative motion measures how quickly the separation changes.','Each mover reduces the gap by its own distance. Per hour, the total decrease is u+v when they approach each other.','Constant speeds along the same line; approaching. Same-direction chasing uses a positive difference.','Estimate a meeting time or a chase.','Choose sum or difference from direction, not from a memorized word.',n=>{let u=30+5*n,v=20+5*n,d=2*(u+v);return pack(`Two people ${d} km apart travel toward one another at ${u} and ${v} km/h. When do they meet?`,2,methods(['Closing speed',`Gap shrinks at ${u+v} km/h.|${d}/(${u}+${v})=2 hours.`],['Distance equation',`${u}t+${v}t=${d}.|t=2.`],['One-hour picture',`After one hour the gap is ${d-u-v}.|The same reduction in the next hour closes it fully.`],['Divide the route',`Distances at meeting are ${2*u} and ${2*v}.|Each divided by its speed gives 2 hours.`],['Stationary-frame model',`Treat one traveler as fixed.|The other approaches at ${u+v} km/h across ${d} km, taking 2 hours.`]),'hours');});
add('trains','Train crossing a platform','Quantitative','Rates & movement','Intermediate','time = (train length + platform length)/speed','The rear of the train must pass the far edge; the front travels both lengths.','When the front reaches the near edge, the rear is one train length behind. Full clearance requires train length plus platform length of travel.','Uniform speed; convert km/h to m/s by multiplying 5/18.','Estimate clearance of a long vehicle past a fixed zone.','Using only platform length measures front travel, not full train clearance.',n=>{let l=100+20*n,p=200+40*n,v=10+2*n;return pack(`A ${l} m train crosses a ${p} m platform at ${v*3.6} km/h. Find the full clearance time.`,30,methods(['Convert then divide',`${v*3.6}×5/18=${v} m/s.|(${l}+${p})/${v}=30 s.`],['Separate the lengths',`Train length time=${l}/${v}=10 s.|Platform time=${p}/${v}=20 s.|Total=30 s.`],['Convert distance to km',`Total distance=${(l+p)/1000} km.|Divide by ${v*3.6} km/h then multiply 3600: 30 s.`],['Position equation',`Front position after t seconds is ${v}t.|For rear clearance, ${v}t=${l+p}; t=30.`],['Scale cancellation',`All lengths and speeds share factor ${n+5}.|Reduced distance/speed ratio still equals 30 s.`]),'seconds');});
add('boats','Boats & streams','Quantitative','Rates & movement','Intermediate','downstream = b+s; upstream = b−s','Water speed changes the boat’s ground speed while its speed relative to water stays constant.','Add velocity in the direction of travel downstream; subtract the opposing stream upstream. Solve two linear equations for b and s.','Straight stream and constant speeds; boat speed greater than stream speed for upstream progress.','Compare travel with and against a moving medium.','Boat speed is half the sum, stream speed half the difference.',n=>{let b=10+2*n,s=2,d=b+s,u=b-s;return pack(`Downstream speed is ${d} km/h and upstream speed ${u} km/h. Find speed in still water.`,b,methods(['Half the sum',`b=(down+up)/2.|(${d}+${u})/2=${b}.`],['Add equations',`b+s=${d}; b−s=${u}.|Add: 2b=${2*b}, so b=${b}.`],['Remove stream',`Stream=(${d}−${u})/2=2.|Downstream minus stream=${b}.`],['Restore upstream',`Stream speed is 2.|Upstream +2=${b}.`],['Midpoint model',`Still-water speed lies equally between ${u} and ${d}.|The midpoint is ${b}.`]),'km/h');});
add('linear','Linear equations','Quantitative','Equations & sequences','Foundation','ax+b=c ⇒ x=(c−b)/a','An equation states that two expressions have the same value. Preserve equality while isolating the unknown.','Subtract b from both sides, then divide both sides by nonzero a.','a must be nonzero for a unique solution.','Recover an unknown unit price from a fixed fee plus a total.','Moving a term is shorthand for applying the same operation to both sides.',n=>{let a=2+n,x=4+n,b=3,c=a*x+b;return pack(`Solve ${a}x + ${b} = ${c}.`,x,methods(['Undo operations',`Subtract ${b}: ${a}x=${c-b}.|Divide by ${a}: x=${x}.`],['Balance model',`Remove ${b} from each side.|Split both sides into ${a} equal groups, giving ${x}.`],['Graph intersection',`Intersect y=${a}x+${b} with y=${c}.|At x=${x}, both heights equal ${c}.`],['Trial with verification',`Try x=${x}.|${a}×${x}+${b}=${c}; the nonzero coefficient makes the solution unique.`],['Scale an offset',`The total above the fixed ${b} is ${c-b}.|Each x contributes ${a}; divide the excess by ${a} to get ${x}.`]));});
add('quadratic','Quadratics & roots','Quantitative','Equations & sequences','Intermediate','x²−(r+s)x+rs=(x−r)(x−s)','A quadratic can encode two possible roots. Factoring finds where its product becomes zero.','Expand (x−r)(x−s) to get x²−(r+s)x+rs. A product of real factors is zero when at least one factor is zero.','These examples have real roots; the general discriminant determines real-root availability.','Investigate intersections or solve a two-solution algebraic model.','A square root step can create two signs; check both.',n=>{let r=2+n,s=r+3,sum=r+s,prod=r*s;return pack(`Find the smaller root of x² − ${sum}x + ${prod} = 0.`,r,methods(['Factor pairs',`Numbers ${r} and ${s} have sum ${sum} and product ${prod}.|Factor (x−${r})(x−${s})=0.|Smaller root=${r}.`],['Quadratic formula',`Discriminant=${sum}²−4×${prod}=9.|x=(${sum}±3)/2; smaller=${r}.`],['Complete the square',`(x−${sum}/2)²=9/4.|x=${sum}/2±1.5; smaller=${r}.`],['Vieta and gap',`Root sum=${sum}; root gap=√9=3.|Smaller=(sum−gap)/2=${r}.`],['Graph and verify',`The parabola crosses at ${r} and ${s}.|Substitute ${r}: ${r*r}−${sum*r}+${prod}=0.|Vertex is between the roots, confirming ${r} is smaller.`]));});
add('ap','Arithmetic progressions','Quantitative','Equations & sequences','Foundation','aₙ = a+(n−1)d','An arithmetic progression adds the same difference at each step.','The first term needs zero increments. Reaching the nth term uses n−1 increments of size d.','Index n is a positive integer; differences must be constant.','Model seats per row or a regularly increasing savings plan.','The nth term uses n−1 increments, not n.',n=>{let a=3+n,d=2+n,k=8,r=a+(k-1)*d;return pack(`An AP starts at ${a} with common difference ${d}. Find its 8th term.`,r,methods(['Term formula',`${a}+7×${d}=${r}.|Eight terms require seven increments.`],['Repeated addition',`Start at ${a}; add ${d} seven times.|The 8th value is ${r}.`],['Pair-index jump',`4th term=${a+3*d}.|Four more increments give ${r}.`],['Linear index rule',`aₖ=${d}k+${a-d}.|At k=8, result=${r}.`],['Backward check',`From ${r}, subtract seven differences ${7*d}.|You recover ${a}, the first term.`]));});
add('area','Area, perimeter & missing sides','Quantitative','Geometry & measurement','Foundation','rectangle area = lw; perimeter = 2(l+w)','Area counts square units of coverage; perimeter measures boundary length.','A rectangle has w rows of l square units, yielding lw. Its four sides total l+w+l+w.','Length and width use the same units; sides are positive.','Plan floor coverage separately from the amount of edging.','Area and perimeter have different units and answer different questions.',n=>{let l=6+n,w=4,r=l*w;return pack(`Find the area of a rectangle ${l} m long and 4 m wide.`,r,methods(['Multiply dimensions',`${l}×4=${r} square meters.|Area uses two length dimensions.`],['Unit-square array',`Four rows each contain ${l} square meters.|Total=${r}.`],['Split the length',`${l}=(4+${l-4}).|Areas 4×4 and ${l-4}×4 total ${r}.`],['Double twice',`Multiplying by 4 is doubling twice.|${l}→${2*l}→${r}.`],['Inverse dimension check',`${r}/4=${l} m.|The recovered length agrees with the given length.`]),'m²',{type:'grid',values:[l,w],labels:['Length','Width']});});
add('volume','Volume & capacity','Quantitative','Geometry & measurement','Foundation','cuboid volume = lwh','Volume measures how many unit cubes fit into a solid.','One base layer has lw unit squares. Stacking h layers produces lwh unit cubes.','Rectangular solid with compatible positive dimensions. 1 m³=1000 liters.','Estimate a rectangular tank’s capacity.','Surface area measures the shell; volume measures the space inside.',n=>{let l=3+n,w=2,h=4,r=l*w*h;return pack(`Find the volume of a cuboid ${l} m ×2 m ×4 m.`,r,methods(['Three-factor product',`${l}×2×4=${r} m³.`],['Base and height',`Base area=${l*2} m².|Four layers give ${r} m³.`],['Choose another base',`Use a 2×4 face: area 8 m².|Stack ${l} layers: ${r} m³.`],['Double three times',`2×4=8.|Double ${l} three times to get ${r}.`],['Capacity check',`Volume ${r} m³ equals ${r*1000} liters.|Divide back by 1000 to recover ${r} m³.`]),'m³');});
add('pythagoras','Right triangles & distance','Quantitative','Geometry & measurement','Foundation','c² = a²+b²','In a right triangle the squared hypotenuse equals the sum of the squared legs.','Arrange four equal right triangles in a square of side a+b. Subtracting their areas leaves c²=a²+b².','A right angle is required; c is opposite it.','Measure a straight diagonal instead of two perpendicular movements.','Never treat a leg as the hypotenuse.',n=>{let k=n+1,a=3*k,b=4*k,c=5*k;return pack(`A right triangle has perpendicular legs ${a} and ${b}. Find its hypotenuse.`,c,methods(['Squares then root',`√(${a}²+${b}²)=√${c*c}=${c}.`],['Scaled 3–4–5 triple',`Both legs are ${k} times 3 and 4.|Hypotenuse is ${k}×5=${c}.`],['Normalize first',`Divide legs by ${k} to get 3 and 4.|Solve the smaller triangle: 5; scale back to ${c}.`],['Coordinate distance',`Points (0,0) and (${a},${b}) have distance √(${a}²+${b}²).|Result=${c}.`],['Area rearrangement',`Outer square area=(${a}+${b})²=${(a+b)**2}.|Four triangle areas total 2ab=${2*a*b}.|Remaining c²=${c*c}, so c=${c}.`]));});
add('trig','Trigonometric ratios','Quantitative','Geometry & measurement','Intermediate','sin θ = opposite / hypotenuse','A right-triangle ratio compares side lengths relative to one chosen acute angle.','Similar right triangles have proportional sides. Dividing corresponding sides removes scale, leaving a ratio determined by the angle.','Right triangle and specified acute angle. Ratio values are dimensionless.','Relate a height to a line of sight.','Opposite depends on the chosen angle; the hypotenuse does not.',n=>{let k=n+1;return pack(`A right triangle has opposite side ${3*k} and hypotenuse ${5*k} for angle θ. Find sin θ.`,.6,methods(['Direct ratio',`${3*k}/${5*k}=3/5=0.6.`],['Cancel scale',`Both sides share factor ${k}.|Use normalized lengths 3 and 5: sin θ=0.6.`],['Percent interpretation',`Opposite is 60% of the hypotenuse.|The ratio is 0.6.`],['Use the cosine identity',`Adjacent leg is ${4*k}, so cos θ=4/5.|sin θ=√(1−(4/5)²)=3/5, positive for an acute angle.`],['Use tangent and normalization',`tan θ=3/4.|sin θ=tan θ/√(1+tan²θ)=(3/4)/(5/4)=3/5.`]));});
add('permutation','Permutations: order matters','Quantitative','Counting & chance','Intermediate','P(n,r)=n!/(n−r)!','A permutation fills distinct positions without reusing an item.','There are n choices for the first position, n−1 for the next, and so on. Multiplying produces the falling factorial.','Distinct items; no replacement; order matters.','Assign first and second prizes to different people.','Swapping winners creates another outcome when prizes differ.',n=>{let a=5+n,r=a*(a-1);return pack(`There are ${a} people. How many ways can different people receive first and second prizes?`,r,methods(['Slot multiplication',`${a} choices for first; ${a-1} for second.|${a}×${a-1}=${r}.`],['Factorial cancellation',`${a}!/(${a-2})! cancels to ${a}×${a-1}.|Result=${r}.`],['Choose pair then order',`Choose 2: ${r/2} unordered pairs.|Each has 2 orders, giving ${r}.`],['Remove repeats',`${a}² ordered pairs allow the same person twice.|Subtract ${a} repeats: ${r}.`],['Group by first winner',`For each of ${a} possible first winners, list ${a-1} seconds.|The groups are disjoint, so total=${r}.`]));});
add('combination','Combinations: order does not matter','Quantitative','Counting & chance','Intermediate','C(n,r)=n!/[r!(n−r)!]','A combination counts a selection without assigning positions.','Each unordered r-member group appears r! times among ordered selections. Divide permutations by r! to remove that repetition.','Distinct items; no replacement; group order irrelevant.','Choose a two-person committee.','Dividing by r rather than r! fails for selections of more than two.',n=>{let a=5+n,r=a*(a-1)/2;return pack(`How many two-person committees can be chosen from ${a} people?`,r,methods(['Combination formula',`${a}×${a-1}/2=${r}.`],['Ordered then divide',`Ordered choices=${a*(a-1)}.|Each committee appears twice, so divide by 2: ${r}.`],['Handshake interpretation',`Count distinct pairs as 1+2+…+${a-1}.|The sum is ${r}.`],['Exclude repeated pairs',`Start with ${a}² ordered pairs.|Remove ${a} self-pairs, then halve: ${r}.`],['Add one person',`Among the first ${a-1}, committees=${(a-1)*(a-2)/2}.|The new person forms ${a-1} new pairs.|Total=${r}.`]));});
add('probability','Probability of an event','Quantitative','Counting & chance','Foundation','P(E)=favorable equally likely outcomes / total outcomes','Probability compares favorable outcomes with all possible outcomes when they are equally likely.','Partition the sample space into equally likely outcomes. Each has probability 1/N; summing f such outcomes gives f/N.','Equally likely outcomes are required for this counting formula.','Model a random draw from a well-mixed bag.','Not every real-world outcome is equally likely.',n=>{let r=3+n,b=2*r;return pack(`A bag has ${r} red and ${b} blue balls. One is drawn uniformly at random. Find P(red), rounded to 6 decimals.`,f(1/3),methods(['Count outcomes',`Red/total=${r}/${r+b}=1/3.`],['Simplify the ratio',`Red:blue=1:2.|Red fraction=1/(1+2)=1/3.`],['Complement',`P(blue)=2/3.|P(red)=1−2/3=1/3.`],['Equal likelihood sum',`Each ball has probability 1/${r+b}.|Sum ${r} red-ball probabilities: 1/3.`],['Partition into groups',`Arrange balls into ${r} groups of 1 red and 2 blue.|Every group has the same red fraction 1/3; overall fraction is 1/3.`]),'probability',{type:'bar',values:[r,b],labels:['Red','Blue']});});
add('table','Reading tables & totals','Data','Tables & charts','Foundation','total = sum of the requested entries','A table places measures at row-column intersections. Identify the correct intersection before calculating.','A total is built by adding disjoint quantities measured in the same units. Labels establish which quantities belong in the sum.','Add only compatible quantities; check whether entries are totals, averages or rates.','Combine daily production counts.','Do not sum a percentage column as if it were a count.',n=>{let v=[40+10*n,60+10*n,80+10*n],r=v.reduce((a,b)=>a+b,0);return pack(`A table shows production: Mon ${v[0]}, Tue ${v[1]}, Wed ${v[2]} units. Find total production.`,r,methods(['Row scan',`Read the three production entries.|${v.join('+')}=${r}.`],['Pair then add',`${v[0]}+${v[2]}=${v[0]+v[2]}.|Add Tuesday ${v[1]}: ${r}.`],['Equal-step average',`The entries form an AP; mean=${v[1]}.|Three days ×${v[1]}=${r}.`],['Reference deviations',`Use ${v[1]} per day.|Deviations −20,0,+20 cancel; total=${3*v[1]}.`],['Running total',`After Tuesday: ${v[0]+v[1]}.|After Wednesday: ${r}; no row is counted twice.`]),'units',{type:'columns',values:v,labels:['Mon','Tue','Wed']});});
add('chart-share','Charts & part-to-whole share','Data','Tables & charts','Foundation','share% = part / total ×100','A chart’s share is the category amount divided by the sum of all categories.','The full chart represents 100%. Scaling each category by 100/total converts counts to percentage shares.','Categories should be disjoint and cover the stated total.','Interpret product sales or a survey distribution.','A taller bar is an amount; it is not automatically a percentage.',n=>{let k=10+n*5,a=2*k,b=3*k,c=5*k;return pack(`Sales are A=${a}, B=${b}, C=${c}. What percentage of all sales is B?`,30,methods(['Total then divide',`Total=${a+b+c}.|${b}/${a+b+c}×100=30%.`],['Reduce the ratio',`A:B:C=2:3:5.|B has 3 of 10 units, or 30%.`],['One-percent amount',`1% of total=${(a+b+c)/100}.|B divided by that amount gives 30%.`],['Complement',`A and C total 70%.|B=100−70=30%.`],['Pie angle conversion',`B occupies 0.3×360=108°.|108/360×100=30%.`]),'percent',{type:'bar',values:[a,b,c],labels:['A','B','C']});});
add('data-growth','Data comparison & growth','Data','Tables & charts','Intermediate','growth% = change / initial ×100','Comparison can ask for an absolute difference, a ratio or a relative change. Read the requested measure first.','Subtract to find change, then normalize by the initial value when the question asks for growth percent.','The initial amount is positive; time periods and measurement definitions match.','Read monthly sales performance.','A 20-unit rise and a 20% rise are not interchangeable.',n=>{let a=100+50*n,b=a*1.4;return pack(`Quarter 1 sales are ${a}; Quarter 2 sales are ${b}. Find sales growth as a percentage of Quarter 1.`,40,methods(['Difference ratio',`Change=${b-a}.|(${b-a}/${a})×100=40%.`],['Factor comparison',`${b}/${a}=1.4.|Excess factor 0.4 gives 40%.`],['Unit baseline',`Set Quarter 1 to 100 normalized units.|Quarter 2 becomes 140; increase=40%.`],['Fraction reduction',`The rise is 2/5 of the initial sales.|2/5=40%.`],['Reconstruct the data',`40% of ${a}=${a*.4}.|Add to ${a} to recover ${b}.`]),'percent',{type:'columns',values:[a,b],labels:['Q1','Q2']});});
add('data-sufficiency','Numerical data sufficiency','Data','Logic & sufficiency','Intermediate','Sufficient ⇔ the requested value is uniquely determined','Data sufficiency asks whether the answer can be determined, even if you are not asked to report that answer.','Try to find two different valid values for the requested output. If both satisfy the information, the data is insufficient.','Evaluate statements alone before combining; use only explicit conditions.','Decide which extra measurement is needed before a calculation.','Having an equation does not guarantee a unique requested value.',n=>{let w=n+3,a=6*w;return pack(`For a rectangle, find its area. I: width=${w}. II: length=6. Which data is sufficient?`,'Both together only',methods(['Test I alone',`Width ${w} allows length 1 or 2, producing different areas.|I is insufficient; II alone also allows different widths.`],['Combine equations',`I fixes width ${w}; II fixes length 6.|Together area=${a}, uniquely determined.`],['Degrees of freedom',`Each single statement leaves a free side.|Both remove the freedom; only the combination is sufficient.`],['Counterexample method',`With I alone, areas ${w} and ${2*w} are both possible.|With II alone, areas 6 and 12 are possible; together only ${a}.`],['Target-focused check',`Area needs the product length×width.|Neither statement fixes that product alone; the combination does.`]),'',null,['I alone','II alone','Both together only','Even together insufficient']);});
const names=['Asha','Bala','Chitra','Dev','Esha'];
add('number-series','Number series & differences','Reasoning','Patterns & codes','Foundation','Inspect differences, ratios and alternating positions','A series question asks for a rule consistent with the displayed entries. Start with the simplest familiar pattern.','Taking adjacent differences can reveal a hidden arithmetic progression. A short finite list never mathematically forces a unique continuation.','Use the specified rule or the simplest conventional rule among the choices.','Recognize a repeated increment in operational data.','One rule fitting two terms may fail the rest.',n=>{let a=2+n,v=[a,a+3,a+6,a+9],r=a+12;return pack(`Using a constant-difference rule, continue ${v.join(', ')}, __.`,r,methods(['Differences',`Every adjacent difference is 3.|Add 3 to ${v[3]}: ${r}.`],['Index rule',`Term k=${a}+3(k−1).|At k=5: ${r}.`],['Number line',`Make four equal jumps of size 3 from ${a}.|The fifth entry is ${r}.`],['Choice elimination',`Only ${r} preserves the final increment of 3.|Check earlier increments too.`],['Backward verification',`${r}−3=${v[3]}.|Continue backward to recover every supplied term.`]));});
add('letter-series','Letter series','Reasoning','Patterns & codes','Foundation','Use alphabet positions A=1,…,Z=26','Convert letters into positions to see a numerical movement rule.','The alphabet creates an ordered set. A constant position increment can be treated like an arithmetic progression.','These examples stay inside A–Z; wrapping must be explicitly specified.','Decode an ordered label pattern.','Do not invent wraparound or a different alphabet unless stated.',n=>{let a=1+n,letters=[a,a+2,a+4,a+6].map(x=>String.fromCharCode(64+x)),r=String.fromCharCode(64+a+8);return pack(`Using a +2 alphabet-position rule: ${letters.join(', ')}, __.`,r,methods(['Position conversion',`${letters.join(', ')} correspond to ${a},${a+2},${a+4},${a+6}.|Next position ${a+8} is ${r}.`],['Skip one letter',`Each move skips one alphabet letter.|After ${letters[3]}, the next selected letter is ${r}.`],['AP formula',`Position 5=${a}+4×2=${a+8}.|Convert to ${r}.`],['Options check',`Reject letters not two places after ${letters[3]}.|${r} matches the specified jump.`],['Reverse rule',`Move back two places from ${r} to ${letters[3]}.|Repeated reversal recovers the series.`]),'',null,[r,String.fromCharCode(65+a+8),String.fromCharCode(63+a+8),String.fromCharCode(66+a+8)]);});
add('coding','Coding & decoding','Reasoning','Patterns & codes','Foundation','Encode each letter with the stated transformation','A code is a mapping. Apply it consistently rather than guessing from the appearance of the output.','A shift code adds the same integer to each alphabet position; decoding subtracts it.','The rule here shifts +1 and no letter wraps around Z.','Understand an illustrative substitution code.','Apply the shift to every letter, including repeated letters.',n=>{let words=['CAT','DOG','HEN','BUS','PEN'],w=words[n%5],r=[...w].map(c=>String.fromCharCode(c.charCodeAt(0)+1)).join('');return pack(`Code every letter by shifting it +1 in the alphabet. What is the code for ${w}?`,r,methods(['Letter by letter',`Shift ${[...w].map((c,i)=>c+'→'+r[i]).join(', ')}.|Join to get ${r}.`],['Position arithmetic',`Add 1 to each alphabet position in ${w}.|Convert the three new positions to ${r}.`],['Mapping table',`Write original and shifted letters in aligned rows.|The output row reads ${r}.`],['Elimination',`A correct option must advance all three letters exactly once.|${r} satisfies all positions.`],['Decode to check',`Move each letter of ${r} backward one place.|Recover ${w}, confirming the code.`]),'',null,[r,w,[...r].reverse().join(''),[...w].map(c=>String.fromCharCode(c.charCodeAt(0)+2)).join('')]);});
add('analogy','Analogies & relationship matching','Reasoning','Patterns & codes','Foundation','A:B :: C:D preserves the stated relationship','An analogy matches a relationship rather than a superficial similarity.','Describe the first pair in a sentence, then require the same sentence structure for the second.','The relation is explicitly square-number mapping in these examples.','Identify a shared transformation across different inputs.','Matching only a size or a spelling can ignore the relationship.',n=>{let a=3+n,b=a+1,r=b*b;return pack(`Under the rule “maps to its square”: ${a}:${a*a} :: ${b}:__ .`,r,methods(['State the relation',`${a*a}=${a}².|Therefore ${b} maps to ${b}²=${r}.`],['Repeated product',`First pair multiplies the number by itself.|${b}×${b}=${r}.`],['Difference of squares',`${b}²−${a}²=(${b}−${a})(${b}+${a})=${a+b}.|Add to ${a*a}: ${r}.`],['Choice validation',`Test each candidate against the required square relation.|Only ${r} equals ${b}².`],['Reverse relationship',`√${a*a}=${a}; √${r}=${b}.|Both pairs obey the same inverse rule.`]));});
add('classification','Classification & odd one out','Reasoning','Patterns & codes','Foundation','Choose the item violating the stated common property','Classification puts objects into groups based on a defined property.','A valid odd-one-out answer needs a property shared by all other options but not by the chosen one.','Here the property is divisibility by 2, so the classification is unambiguous.','Detect an item outside a numeric category.','Without a stated property, several classifications can be defensible.',n=>{let a=2+n*2,v=[a,a+2,a+4,a+5],r=a+5;return pack(`Which is not even: ${v.join(', ')}?`,r,methods(['Last digit',`The first three end in even digits.|${r} ends in an odd digit.`],['Remainder test',`${r} mod 2=1.|The others have remainder 0.`],['Pairing model',`An even count can be grouped entirely in pairs.|${r} leaves one item unpaired.`],['Form 2k',`The first three equal 2 times an integer.|${r} cannot be written as 2k for integer k.`],['Eliminate category members',`Remove ${v.slice(0,3).join(', ')} as even.|The remaining value is ${r}.`]),'',null,v);});
add('directions','Directions & displacement','Reasoning','Spatial & arrangement','Foundation','net east = east−west; net north = north−south','Track a route on perpendicular axes. Final direction depends on the net displacement, not the last movement.','Choose east as positive x and north as positive y. Add signed movements to find the final coordinate.','Compass directions and straight movements; no map distortions.','Find the final position after a delivery route.','Total distance traveled differs from straight-line displacement.',n=>{let e=5+n,w=2+n,nn=4+n;return pack(`Walk ${e} m east, ${nn} m north, then ${w} m west. In which direction is the final point from the start?`,'North-east',methods(['Coordinate addition',`Net x=${e}−${w}=3; net y=${nn}.|Both positive means north-east.`],['Sketch route',`Draw east, north, then a shorter west arrow.|Endpoint stays east and north of the start.`],['Cancel opposing steps',`Cancel ${w} east against ${w} west.|Remaining: 3 east and ${nn} north.`],['Quadrant test',`Positive east and positive north place the endpoint in the NE quadrant.|Direction is north-east.`],['Eliminate directions',`The endpoint is neither west nor south.|It is not directly north since x=3; select north-east.`]),'',{type:'route',values:[3,nn],labels:['East','North']},['North-east','North-west','South-east','North']);});
add('blood','Blood relations & family trees','Reasoning','Spatial & arrangement','Foundation','Translate each explicit relationship into a family tree','Family problems require linking generations and checking exactly whose relationship is being asked.','Parent-child edges move one generation; siblings share a parent in these examples. Gender must come from the given facts.','Use only stated facts. Here family links are explicit and no additional marriages are assumed.','Interpret a family connection accurately.','Do not infer gender from a name.',n=>{let name=names[n];return pack(`${name} is the mother of Ravi. Ravi is the father of Tara. How is ${name} related to Tara?`,'Grandmother',methods(['Generation chain',`${name}→Ravi→Tara has two parent-child steps.|A female ancestor two generations above is a grandmother.`],['Start at Tara',`Tara’s father is Ravi.|Ravi’s mother is ${name}, so ${name} is Tara’s paternal grandmother.`],['Draw a tree',`Place ${name} above Ravi and Ravi above Tara.|Two levels plus stated female parent gives grandmother.`],['Relation composition',`Mother of father = paternal grandmother.|The result is grandmother.`],['Eliminate roles',`Mother would be one generation above; sister is the same generation.|Two generations above excludes these options.`]),'',null,['Grandmother','Mother','Sister','Daughter']);});
add('ranking','Ranking & ordering','Reasoning','Spatial & arrangement','Foundation','total = rank from top + rank from bottom −1','Two ranks count the same person from opposite ends.','Adding both ranks counts the person twice. Subtract one to count each person exactly once.','A complete linear ranking with no tied positions.','Recover the size of a ranked queue.','Forgetting −1 counts the named person twice.',n=>{let a=4+n,b=7+n,r=a+b-1;return pack(`${names[n]} ranks ${a}th from the top and ${b}th from the bottom, with no ties. How many people are there?`,r,methods(['Rank formula',`${a}+${b}−1=${r}.`],['Count neighbors',`Above=${a-1}; below=${b-1}.|Add the person: ${a-1}+1+${b-1}=${r}.`],['Position equation',`Bottom rank=N−top rank+1.|${b}=N−${a}+1, so N=${r}.`],['Queue drawing',`Draw ${a-1} people, the named person, then ${b-1}.|Total positions=${r}.`],['Reverse check',`In ${r} positions, rank ${a} from top becomes ${r}−${a}+1=${b} from bottom.|Both ranks agree.`]));});
add('linear-arrangement','Linear seating arrangements','Reasoning','Spatial & arrangement','Intermediate','Place fixed positions before testing flexible clues','An arrangement must satisfy every constraint at once. Start with restrictive clues.','Adjacent and immediate-left constraints reduce the available orderings; fixed endpoints anchor orientation.','All people face north, so their left matches the diagram’s left. No positions are shared.','Organize people or items under placement constraints.','Facing south reverses a person’s left and right.',n=>{let a=names[n],b='Ravi',c='Tara';return pack(`Three people face north. ${a} is at the left end; Ravi sits immediately to ${a}’s right. Who sits at the right end?`,c,methods(['Fill positions',`Left position=${a}; middle=Ravi.|Only Tara remains for the right end.`],['Adjacent block',`The ordered block is ${a}–Ravi.|With ${a} leftmost, Tara must follow it.`],['Permutation elimination',`Reject orders without ${a} first.|Reject those without Ravi second; remaining order ends in Tara.`],['Constraint table',`Position 1 allows only ${a}; position 2 requires Ravi.|Position 3 must be Tara.`],['Verify all clues',`Order ${a},Ravi,Tara places ${a} left and Ravi immediately right.|All three distinct seats are used; answer Tara.`]),'',null,['Tara','Ravi',a,'Cannot determine']);});
add('circular','Circular arrangements','Reasoning','Spatial & arrangement','Intermediate','Distinct circular orders = (n−1)!','On an unmarked circle, rotating everyone together does not create a new order.','Fix one person as an anchor. Permute the remaining n−1 people around that anchor.','Distinct people; rotations equivalent; reflections distinct; no seat labels or additional constraints.','Count circular seating plans without a labeled starting seat.','Numbered seats remove rotational equivalence and require n!, not (n−1)!.',n=>{let a=3+n,fact=k=>k<2?1:k*fact(k-1),r=fact(a-1);return pack(`How many circular orders for ${a} distinct people if rotations are identical but reflections count separately?`,r,methods(['Anchor one person',`Fix one person at the top.|Arrange ${a-1} others: (${a-1})!=${r}.`],['Linear then quotient',`Numbered-seat orders=${fact(a)}.|Each circle has ${a} rotated copies; divide to get ${r}.`],['Sequential placement',`After the anchor, choices are ${Array.from({length:a-1},(_,i)=>a-1-i).join('×')}.|Their product is ${r}.`],['Rotation classes',`Each class contains ${a} distinct rotations because people are distinct.|${a}!/${a}=${r}.`],['Insert the newest person',`There are (${a-2})!=${fact(a-2)} orders for the first ${a-1}.|Insert the newest into ${a-1} gaps: ${r}.`]));});
add('syllogism','Syllogisms & set logic','Reasoning','Logic & deduction','Intermediate','All A are B; all B are C ⇒ all A are C','Syllogisms ask what necessarily follows from stated relationships among sets.','If A is contained in B and B in C, every member of A is contained in C by transitivity.','Universal premises alone do not assert that the sets contain members.','Test a conclusion against a chain of category rules.','Reversing “all A are B” into “all B are A” is invalid.',n=>{let a=['roses','sparrows','squares','apples','violins'][n],b=['flowers','birds','rectangles','fruits','instruments'][n],c=['plants','animals','quadrilaterals','foods','objects'][n];return pack(`All ${a} are ${b}. All ${b} are ${c}. Must all ${a} be ${c}?`,'Yes',methods(['Containment chain',`${a} ⊆ ${b} ⊆ ${c}.|Therefore ${a} ⊆ ${c}.`],['Arbitrary member',`Choose any member of ${a}, if one exists.|It belongs to ${b}, then to ${c}, proving the universal implication.`],['Nested set picture',`Draw A entirely inside B and B inside C.|No A region lies outside C.`],['Counterexample attempt',`Suppose an A is outside C.|It must be B by premise 1, but all B are C, a contradiction.`],['Implication composition',`A→B and B→C.|Composition gives A→C; no converse or existence claim is needed.`]),'',null,['Yes','No','Only if some C are A','Cannot determine']);});
add('inequalities','Inequalities & comparison chains','Reasoning','Logic & deduction','Foundation','a>b and b>c ⇒ a>c','Order comparisons can be linked only when their directions support a chain.','On a number line, if a is right of b and b right of c, then a is right of c.','Strict and non-strict relations must be distinguished. Opposing branches may leave a relation unknown.','Compare rankings or measured amounts from partial information.','a>b and c>b do not determine whether a>c.',n=>{let a=names[n];return pack(`Given ${a} > Ravi and Ravi > Tara for their numerical scores, which comparison must hold?`,`${a} > Tara`,methods(['Chain',`${a} > Ravi > Tara.|Thus ${a} > Tara.`],['Number line',`Put Tara left of Ravi and ${a} right of Ravi.|${a} is right of Tara.`],['Positive differences',`${a}−Ravi>0 and Ravi−Tara>0.|Add: ${a}−Tara>0.`],['Contradiction',`Assume ${a}≤Tara.|That conflicts with ${a}>Ravi>Tara, so the assumption fails.`],['Options elimination',`Equality and reversed order conflict with the strict chain.|Only ${a}>Tara is forced.`]),'',null,[`${a} > Tara`,`${a} = Tara`,`${a} < Tara`,'Cannot determine']);});
add('calendar','Calendars & day shifts','Reasoning','Time & visual reasoning','Foundation','day shift = elapsed days mod 7','Weekdays repeat in cycles of seven; complete weeks leave the day unchanged.','Split elapsed days into full groups of seven plus a remainder. Only the remainder shifts the weekday.','Count elapsed days, not both endpoints. Leap-year questions need the actual year rule.','Determine a weekday after an interval.','Counting the starting day as day one creates an off-by-one error.',n=>{let d=10+7*n;return pack(`Today is Monday. What weekday will it be after ${d} elapsed days?`,'Thursday',methods(['Remainder',`${d} mod 7=3.|Three days after Monday is Thursday.`],['Remove weeks',`Remove ${Math.floor(d/7)} full weeks.|Remaining 3 days lead to Thursday.`],['Day indices',`Monday=0, Tuesday=1,…,Sunday=6.|(0+${d}) mod 7=3, Thursday.`],['Short count',`Tuesday after 1 day; Wednesday after 2; Thursday after 3.|Whole weeks preserve the result.`],['Reverse check',`Move back 3 days from Thursday to Monday.|Adding or removing full weeks does not change it.`]),'',null,['Thursday','Wednesday','Friday','Monday']);});
add('clock','Clocks & relative angular motion','Reasoning','Time & visual reasoning','Intermediate','angle = |30h−5.5m|; smaller angle = min(angle,360−angle)','Both hands move. The hour hand shifts half a degree per minute, rather than staying exactly on its hour mark.','Minute hand: 360/60=6° per minute. Hour hand: 360/12=30° per hour plus 0.5° per minute. Subtract their positions.','h is reduced modulo 12 and 0≤m<60. Take the smaller angle when requested.','Model two rotating indicators at different rates.','Ignoring the hour hand’s minute movement changes the angle.',n=>{let h=2+n,m=20,a=Math.abs(30*h-5.5*m),r=Math.min(a,360-a);return pack(`Find the smaller angle between clock hands at ${h}:20.`,r,methods(['Absolute positions',`Minute hand=120°; hour hand=${30*h+10}°.|Difference=${a}°; smaller angle=${r}°.`],['Relative-rate formula',`abs(30×${h}−5.5×20)=${a}.|Choose min(${a},${360-a})=${r}.`],['From the hour mark',`At ${h}:00, hour hand is ${30*h}°.|In 20 minutes it gains 10° while minute hand moves to 120°.|Gap=${r}°.`],['Dial intervals',`Each numbered interval is 30°.|Hour hand is 1/3 interval beyond ${h}; minute hand is at 4.|The smaller separation is ${r}°.`],['Around-the-circle check',`The two separating arcs total 360°.|Their measures are ${a} and ${360-a}; select ${r}.`]),'degrees');});
add('cubes','Painted cubes & exposed faces','Reasoning','Time & visual reasoning','Intermediate','exactly 2 painted faces = 12(n−2)','Subcubes with exactly two painted faces lie on the edges but not at the corners.','A cube has 12 edges. Each edge has n−2 non-corner subcubes; every such subcube belongs to exactly one edge.','All six outer faces painted; n×n×n equal subcubes with integer n≥2.','Classify positions in a 3D grid.','Corners have three painted faces and must be excluded.',n=>{let k=3+n,r=12*(k-2);return pack(`Paint all outer faces of a cube and cut it into ${k}×${k}×${k} equal cubes. How many have exactly two painted faces?`,r,methods(['Edge formula',`12 edges ×(${k}−2) interior positions.|Result=${r}.`],['One edge model',`Each edge has ${k} subcubes.|Remove its two corners, leaving ${k-2}; repeat for 12 edges: ${r}.`],['Layers',`Top and bottom layers each contribute 4(${k}−2).|Middle layers contribute 4 each across ${k-2} layers.|Total=12(${k}−2)=${r}.`],['Face incidence',`Each of 6 faces has 4(${k}−2) non-corner edge cells.|Each target cell is counted on 2 faces.|6×4×${k-2}/2=${r}.`],['Exclude other classes',`Total ${k**3}; subtract 8 corners, ${6*(k-2)**2} face interiors and ${(k-2)**3} unpainted interiors.|Remaining=${r}.`]));});
add('indices','Indices & powers','Arithmetic','Number foundations','Intermediate','aᵐ × aⁿ = aᵐ⁺ⁿ','A positive integer exponent counts repeated factors of the same base.','Joining m copies of a with n more copies creates m+n copies. The same-base condition is essential.','These examples use positive integer exponents; fractional and negative exponents need additional domain rules.','Simplify repeated scaling before doing arithmetic.','You add exponents only when multiplying equal bases, not when adding powers.',n=>{let a=2+n,r=a**5;return pack(`Evaluate ${a}² × ${a}³.`,r,methods(['Exponent law',`${a}²×${a}³=${a}⁵.|The value is ${r}.`],['Repeated factors',`There are 2+3=5 copies of ${a}.|Their product is ${r}.`],['Evaluate separately',`${a}²=${a*a}; ${a}³=${a**3}.|Multiply: ${r}.`],['Square of the square',`${a}⁴=(${a}²)²=${a**4}.|Multiply by one more ${a}: ${r}.`],['Inverse division check',`${r}/${a**3}=${a*a}.|This recovers ${a}².`]));});
add('surds','Surds & exact simplification','Arithmetic','Number foundations','Intermediate','√(k²a)=k√a for k≥0','A square root is the nonnegative number whose square is the input. Perfect-square factors can be taken outside the root.','For nonnegative values, √(uv)=√u√v. If u=k², its principal square root is k.','Real square roots require nonnegative inputs. √(x²)=|x|, not always x.','Retain an exact diagonal length before rounding it.','√(a+b) is generally not √a+√b.',n=>{let k=2+n,a=2*k*k,r=`${k}√2`;return pack(`Simplify √${a} into k√2 form.`,r,methods(['Perfect-square factor',`${a}=${k*k}×2.|√${a}=${k}√2.`],['Repeated factor pair',`${a}=${k}×${k}×2.|Extract the paired factor: ${k}√2.`],['Compare to √2',`√${a}/√2=√(${a}/2)=√${k*k}=${k}.|Therefore result=${k}√2.`],['Square to verify',`(${k}√2)²=${k*k}×2=${a}.|The candidate is nonnegative, so it is the principal root.`],['Coefficient equation',`Let √${a}=x√2 with x≥0.|Squaring gives 2x²=${a}; x=${k}.`]),'',null,[r,`${k+1}√2`,`${k}√3`,`${k*2}√2`]);});
add('inverse','Inverse proportion','Arithmetic','Ratios & percentages','Intermediate','x₁y₁ = x₂y₂','When a fixed total workload is spread across more identical workers, time decreases inversely with worker count.','For fixed work W and equal per-worker rate r, W=workers×r×time. Therefore workers×time=W/r is constant.','Equal constant worker rates, fixed work, no coordination loss.','Estimate a staffing change under an ideal equal-productivity model.','Double the workers halves time only when the model’s assumptions hold.',n=>{let a=4+n,t=12,b=2*a;return pack(`${a} equal-rate workers finish fixed work in 12 days. How many days would ${b} workers need under the same conditions?`,6,methods(['Constant product',`${a}×12=${b}×t.|t=6 days.`],['Scale efficiency',`Worker count doubles.|Completion time halves: 12/2=6.`],['Worker-days',`Work requires ${a*12} worker-days.|Divide by ${b}: 6 days.`],['Combined rate',`Original team rate=1/12 job/day.|New team rate=2/12=1/6; time=6 days.`],['Completion check',`${b} workers ×6 days=${a*12} worker-days.|The original and new capacity match.`]),'days');});
add('circle','Circles: radius, area & scaling','Quantitative','Geometry & measurement','Intermediate','A=πr²; area scale = (radius scale)²','A circle’s area depends on the square of its radius, so linear size and coverage grow differently.','Thin sectors can be rearranged toward a rectangle with height r and base πr. Their area tends to πr².','Positive radii; same area units; use the stated value of π or leave it exact.','Compare circular coverage of two sprinklers.','Doubling the radius quadruples area.',n=>{let a=n+2,b=2*a;return pack(`A circle’s radius grows from ${a} to ${b} units. By what factor does its area grow?`,4,methods(['Area ratio',`π×${b}²/(π×${a}²)=4.|π cancels.`],['Scale law',`Radius factor=${b}/${a}=2.|Area factor=2²=4.`],['Normalize the circles',`Compare radius 1 with radius 2.|Areas π and 4π have factor 4; scaling both leaves that ratio unchanged.`],['Two-dimensional scaling',`Horizontal and vertical lengths both double.|Coverage multiplies by 2×2=4.`],['Percent cross-check',`A doubling of radius makes area 400% of its old value.|New/old=4; increase is 300%, not 400%.`]),'times');});
add('cylinder','Cylinders & capacity','Quantitative','Geometry & measurement','Intermediate','V=πr²h','A cylinder stacks identical circular cross-sections through its height.','Each thin layer has area πr². Summing the layers over height h gives V=πr²h.','Right circular cylinder, positive dimensions; use consistent units.','Compute the space inside a cylindrical container.','The radius is half the diameter, so substituting diameter as radius multiplies volume by four.',n=>{let r=2+n,h=7,v=22*r*r;return pack(`Find the volume of a cylinder of radius ${r} cm and height 7 cm. Use π=22/7.`,v,methods(['Substitute',`(22/7)×${r}²×7.|Cancel 7 to get 22×${r*r}=${v}.`],['Base and height',`Base area=(22/7)×${r*r}.|Multiply by 7 layers: ${v}.`],['Cancel before multiplying',`The height 7 cancels π’s denominator 7.|Compute 22×${r}×${r}=${v}.`],['Scale radius 1 model',`A radius-1 height-7 cylinder has volume 22.|Radius ${r} multiplies volume by ${r*r}, giving ${v}.`],['Recover the height',`${v}/[(22/7)×${r*r}]=7.|The reconstructed height matches the given height.`]),'cm³');});
add('without-replacement','Probability without replacement','Quantitative','Counting & chance','Advanced','P(A and B)=P(A)P(B given A)','Removing an item changes the next draw’s sample space, so draws without replacement are dependent.','To count two successive successes, multiply the first success probability by the second probability conditioned on the first success.','Uniform draws; two balls drawn successively without replacement. There are at least two red balls.','Model two samples taken from a batch without putting the first back.','Squaring the first-draw probability incorrectly assumes the bag stays unchanged.',n=>{let red=3+n,total=2*red,p=red/total*(red-1)/(total-1);return pack(`A bag has ${red} red and ${red} blue balls. Draw twice without replacement. Find P(both red), rounded to 6 decimals.`,f(p),methods(['Conditional product',`First red=${red}/${total}.|Second red after first red=${red-1}/${total-1}.|Product=${f(p)}.`],['Ordered outcomes',`Favorable ordered pairs=${red}×${red-1}.|All ordered pairs=${total}×${total-1}.|Ratio=${f(p)}.`],['Unordered combinations',`Favorable pairs=C(${red},2)=${red*(red-1)/2}.|Total pairs=C(${total},2)=${total*(total-1)/2}.|Ratio=${f(p)}.`],['Probability tree',`Take the red branch with probability 1/2.|From it, the remaining red branch has probability ${red-1}/${total-1}.|The red-red path weighs ${f(p)}.`],['Complement classification',`The probability of mixed colors is ${f(red/(total-1))}.|Red-red and blue-blue are equal by symmetry.|Each is half the remaining probability: ${f(p)}.`]),'probability');});
add('venn','Venn diagrams & inclusion–exclusion','Reasoning','Logic & deduction','Intermediate','|A ∪ B|=|A|+|B|−|A ∩ B|','Two overlapping categories count shared members twice when their totals are added.','Split A into A-only plus overlap and B into B-only plus overlap. Subtract one overlap to leave each person counted once.','Counts are distinct people in the same population; the overlap is included in each group total.','Count participants interested in at least one activity.','At least one includes both; exactly one excludes the overlap.',n=>{let a=20+5*n,b=30+5*n,i=10+n,r=a+b-i;return pack(`${a} people like tea, ${b} like coffee, and ${i} like both. How many like at least one?`,r,methods(['Inclusion–exclusion',`${a}+${b}−${i}=${r}.`],['Disjoint regions',`Tea only=${a-i}; coffee only=${b-i}; both=${i}.|Add three disjoint regions: ${r}.`],['Tea then new coffee members',`Count ${a} tea members first.|Only ${b-i} coffee members are new.|Total=${r}.`],['Coffee then new tea members',`Count ${b} coffee members first.|Add ${a-i} tea-only members: ${r}.`],['Count exactly one then both',`Exactly one=${a+b-2*i}.|Add both ${i}: ${r}.`]));});
add('conditional-logic','Conditional statements & contrapositives','Reasoning','Logic & deduction','Advanced','P→Q is equivalent to not Q→not P','A conditional says that whenever P occurs, Q must follow. It does not say that Q occurs only through P.','If Q is false while P is true, P→Q would be violated. Therefore not Q forces not P; this is the contrapositive.','Use a stated necessary consequence, not a probabilistic association. Do not infer the converse.','Test an eligibility rule or a logical implication.','Q being true does not prove P; other causes of Q may exist.',n=>{let codes=['A1','B2','C3','D4','E5'],code=codes[n];return pack(`Rule: if a file has tag ${code}, it must be archived. File X is not archived. Can X have tag ${code}?`,'No',methods(['Contrapositive',`Tag→archived.|Not archived→not tagged; answer No.`],['Contradiction',`Assume X has the tag.|The rule makes it archived, contradicting the given fact.`],['Allowed cases',`The tagged-and-not-archived case is forbidden.|X is not archived, so it must be untagged.`],['Set picture',`Tagged files lie entirely inside archived files.|A file outside archived cannot be inside tagged.`],['Consequence test',`Check what the tag would require: archived status.|That requirement fails for X, so the tag is impossible.`]),'',null,['No','Yes','Only on weekends','Cannot determine']);});
add('arguments','Critical reasoning: correlation & causes','Reasoning','Logic & deduction','Advanced','Association alone does not establish causation','Two observations can move together because of a third factor, reverse causation or chance.','A causal claim needs evidence ruling out plausible alternative explanations, not just a before-after observation.','The question asks whether the evidence guarantees causation; it does not ask whether causation is possible.','Evaluate a claim that a new study tool improved exam results.','A higher score after using a tool could also reflect extra practice or a different test.',n=>{let tools=['flashcards','a timer','a new notebook','a revision app','a study playlist'];return pack(`A learner used ${tools[n]} and then scored higher. No other information is given. Does this prove the tool caused the improvement?`,'No',methods(['Alternative cause',`The learner may have practised more.|That can explain improvement without a tool effect, so causation is not proved.`],['Missing comparison',`There is no matched comparison of performance with and without the tool.|The observation alone cannot isolate an effect.`],['Changed measurement',`The later test may have been easier.|A different test can produce a higher score without greater ability.`],['Counterexample',`Imagine the tool has no effect but extra study raises the score.|This fits the observation and refutes guaranteed causation.`],['Claim strength',`The evidence shows “after”, not “because”.|The correct conclusion is that causation is possible but unestablished.`]),'',null,['No','Yes','Only if the increase is large','All improvements have one cause']);});
add('input-output','Input–output machine rules','Reasoning','Patterns & codes','Intermediate','Track the stated operation at each stage','An input-output machine applies transformations in order. Maintain a record of the value after every step.','For a machine that doubles then adds 3, the combined rule is y=2x+3. Reversing uses subtraction then division.','The machine’s order is explicitly given; it cannot be swapped arbitrarily.','Interpret a calculation pipeline or a coding puzzle.','Adding first and doubling afterward adds 6 instead of 3.',n=>{let x=4+n,r=2*x+3;return pack(`A machine doubles the input, then adds 3. What output does input ${x} produce?`,r,methods(['Stage trace',`${x}→${2*x} after doubling.|Then +3 gives ${r}.`],['Combined expression',`y=2x+3.|Substitute x=${x}: ${r}.`],['Repeated addition',`${x}+${x}+3=${r}.`],['Reverse verification',`${r}−3=${2*x}.|Divide by 2 to recover ${x}.`],['Order comparison',`Adding 3 first then doubling gives ${2*x+6}.|Remove the extra 3 to recover the specified output ${r}.`]));});
export const examLessons=list;
export const examAreas=['Arithmetic','Quantitative','Reasoning','Data'];
export function examCase(id,index=0){const lesson=list.find(x=>x.id===id);if(!lesson)throw new Error('Unknown lesson');const n=Math.abs(Math.trunc(index))%5;const c=lesson.build(n);const answer=typeof c.answer==='number'?f(c.answer):c.answer;let options=c.options||(c.unit==='probability'?[answer,f(1-Number(answer)),0.5,0.25]:id==='trig'?[answer,0.8,0.75,0.4]:[answer,f(Number(answer)+2),f(Number(answer)-1),f(Number(answer)+5)]);options=[...new Set(options)];if(options.length!==4)throw new Error('Duplicate choices: '+id);return {...c,answer,options:[...options.slice(n%4),...options.slice(0,n%4)],id:id+'-'+n,lessonId:id,index:n};}
export function correctExamAnswer(value,answer){if(value===null||value===undefined||String(value).trim()==='')return false;return typeof answer==='number'?Number.isFinite(Number(value))&&Math.abs(Number(value)-answer)<=1e-5:String(value).trim()===String(answer);}
export function practiceSet({area='All',topic='All',level='All',seed=0,count=10}={}){const pool=list.filter(l=>(area==='All'||l.area===area)&&(topic==='All'||l.topic===topic)&&(level==='All'||l.level===level)).flatMap(l=>Array.from({length:5},(_,i)=>examCase(l.id,i)));if(!pool.length)return [];let state=(seed+1)>>>0;for(let i=pool.length-1;i>0;i--){state=(state*1664525+1013904223)>>>0;let j=state%(i+1);[pool[i],pool[j]]=[pool[j],pool[i]];}return pool.slice(0,Math.min(count,pool.length));}
export function scoreExam(questions,answers,penalty=0){const correct=questions.filter(q=>correctExamAnswer(answers[q.id],q.answer)).length;const attempted=questions.filter(q=>answers[q.id]!==undefined&&answers[q.id]!==null&&String(answers[q.id]).trim()!=='').length;return {correct,wrong:attempted-correct,skipped:questions.length-attempted,score:f(correct-(attempted-correct)*penalty),accuracy:attempted?Math.round(correct/attempted*100):0};}

